async function readBuildInput(input){const text=input.trim();if(text.startsWith('AAC1.')||text.startsWith('AAC2.'))return P.decodeShort(text,DB,rules);let id=text;if(/^https?:\/\//i.test(text)){const url=new URL(text);if(url.origin!==location.origin)throw Error('Use a link from this Gear Planner website.');id=url.searchParams.get('s')||'';}if(!/^[A-Za-z0-9]{6}$/.test(id))throw Error('Paste a valid share link, ID, AAC1 or AAC2 code.');const response=await fetch('/api/builds/'+id);const data=await response.json();if(!response.ok)throw Error(data.error||'Build link could not be loaded.');return P.validate(data.build,DB,rules);}
