for(const [id,label]of P.slots){const option=el('option',label);option.value=id;$('inventorySlot').append(option);}$('addInventory').onclick=()=>{if(!loaded)return toast('Wait for the catalog to load.');if((state.inventory||[]).length>=48)return toast('Inventory is full.');inventoryMode=true;inventoryEditing=null;openSlot($('inventorySlot').value);};$('closeInventory').onclick=()=>$('inventoryDialog').close();$('swapInventory').onclick=()=>{try{state=P.swap(state,inventorySelected,$('swapSlot').value,DB,rules);$('inventoryDialog').close();render();toast('Equipment swapped.');}catch(e){toast(e.message);}};$('removeInventory').onclick=()=>{state.inventory.splice(inventorySelected,1);$('inventoryDialog').close();renderInventory();};$('editInventory').onclick=()=>{const entry=state.inventory[inventorySelected];inventoryMode=true;inventoryEditing=inventorySelected;$('inventoryDialog').close();openSlot(entry.slot);itemDetail(find('items',entry.id));};
let migrationDraft={},migrationRows={};
migrationButton.onclick=()=>{migrationDraft={...state.migration};migrationRows={};const box=$('migrationFields');box.replaceChildren();for(const key of ['str','int','dex','spi','sta']){const row=el('div',undefined,'migration-row'),label=el('div',CharacterStats.effects[key][0],'migration-label'),controls=el('div',undefined,'migration-controls'),value=el('div',undefined,'migration-value'),total=el('strong'),delta=el('small');value.append(total,delta);const buttons=[];for(const step of [-100,-10,-5,5,10,100]){if(step===5)controls.append(value);const button=el('button',(step>0?'+':'')+step);button.type='button';button.setAttribute('aria-label',CharacterStats.effects[key][0]+' '+(step>0?'+':'')+step);button.onclick=()=>{migrationDraft[key]+=step;migrationPreview();};controls.append(button);buttons.push({button,step});}row.append(label,controls);box.append(row);migrationRows[key]={total,delta,buttons};}migrationPreview();$('migrationDialog').showModal();};
