async function init(){loaded=false;$('status').textContent='Loading catalogs…';$('refresh').disabled=true;try{await Promise.all(['items','buffs','skills'].map(async k=>DB[k]=await api(k,'_index')));const effectResponse=await fetch('/equipment-effects.json');if(!effectResponse.ok)throw Error('Equipment effect data unavailable');effectDB=await effectResponse.json();const r=await fetch('/rules.json');if(r.ok)rules=await r.json();for(const i of DB.items){const a=rules.synthesis_items?.[String(i.id)]||rules.armors?.[String(i.id)]||rules.accessories?.[String(i.id)];if(a)i.db_slot=a.slot_type_id;}loaded=true;$('status').textContent=`${DB.items.length.toLocaleString('en-US')} items · local catalog · Oct 11, 2026`;render();if(!sharedLinkLoaded){sharedLinkLoaded=true;const id=new URL(location.href).searchParams.get('s');if(id){try{state=await readBuildInput(id);hydrate();toast('Shared build loaded.');}catch(error){toast(error.message);}}}}catch(e){$('status').textContent='Loading failed';toast(e.message);}finally{$('refresh').disabled=false;}}$('refresh').onclick=()=>{details.clear();init();};render();init();

function enchantmentChoices(item){const seen=new Set();return DB.items.filter(g=>Sockets.enchantCompatible(g,item,rules)).sort((a,b)=>Math.max(0,b.grade)-Math.max(0,a.grade)||a.name.localeCompare(b.name,'en')||a.id-b.id).filter(g=>{const e=EquipmentEffects.itemEffects(g,Math.max(0,g.grade),effectDB);if(!e.entries.length||e.pending.length)return true;const key=JSON.stringify([e.entries.map(x=>[x.attribute,x.value,x.unit]).sort((a,b)=>JSON.stringify(a).localeCompare(JSON.stringify(b))),[...new Set(rules.enchants[g.id].map(r=>r.eiset_id).filter(Boolean))].sort((a,b)=>a-b)]);if(seen.has(key))return false;seen.add(key);return true;});}
var hoverCard;
function gemEffectText(g){const entries=EquipmentEffects.itemEffects(g,Math.max(0,g.grade),effectDB).entries,special=effectDB.gem_special_effects?.[g.id]||[];return [...entries,...special].map(e=>e.name+' '+(special.includes(e)&&e.value>0?'+':'')+Number(e.value.toFixed(3))+e.unit).join(', ')||'Effect data unavailable';}
function attachTooltip(target,item,entry){let card,leaveTimer;function hide(){card?.remove();if(hoverCard===card)hoverCard=null;}function show(){hoverCard?.remove();card=el('aside',undefined,'item-tooltip');hoverCard=card;card.setAttribute('role','tooltip');card.addEventListener('mouseenter',()=>clearTimeout(leaveTimer));card.addEventListener('mouseleave',hide);const header=el('div',undefined,'tooltip-header');header.append(itemIcon(item,'◈',entry.grade),el('strong',item.name));const score=C.itemScore(item,entry,rules);card.append(header,el('div','Equipment Points: '+Number(score.total.toFixed(1))+' ('+Number(score.base.toFixed(1))+' + '+Number(score.modifications.toFixed(1))+')'+(score.pending.length?' · Partial':'')),el('small',`${grades[entry.grade]} · ${item.category} · Lv. ${item.level} · #${item.id}`));const values=C.itemValues(item,entry.grade,rules,entry.temper);for(const key of ['defense','magic_defense','dps','mdps','hdps'])if(values[key]!=null)card.append(el('div',({defense:'Physical Defense',magic_defense:'Magic Defense',dps:'Melee / Ranged DPS',mdps:'Magic DPS',hdps:'Healing DPS'})[key]+': '+(['defense','magic_defense'].includes(key)?Math.round(values[key]):Number(values[key].toFixed(2)))));for(const [key,value]of Object.entries({...values.stats,...entry.baseStats}))if(value!==0)card.append(el('div',(CharacterStats.effects[key]?.[0]||key)+': +'+value));const effects=EquipmentEffects.itemEffects(item,entry.grade,effectDB);const setIds=[...(rules.enchants[item.id]||[]).map(r=>r.eiset_id),effectDB.items[item.id]?.eiset_id,...(rules.enchants[entry.enchant||entry.lunasigil]||[]).map(r=>r.eiset_id)].filter(Boolean);const audit=EquipmentEffects.buildEffects(state,DB.items,effectDB,rules);for(const id of [...new Set(setIds)]){card.append(el('h4','Set #'+id));for(const bonus of effectDB.sets[id]||[]){const active=audit.sets.some(x=>x.id===id&&x.pieces>=bonus.num_pieces);const parts=bonus.verified_override?[bonus.verified_override]:EquipmentEffects.setTierModifiers(id,bonus,effectDB).map(m=>{const entry=EquipmentEffects.resolve(m,item.level,effectDB);return m.unit_modifier_type_id===1?{name:effectDB.attributes[m.unit_attribute_id]?.name||'Attribute #'+m.unit_attribute_id,value:EquipmentEffects.roundEven(m.value+m.linear_level_bonus*item.level/100),unit:'% of base'}:entry;}).filter(e=>!e.reason);card.append(el('div',`[${bonus.num_pieces} pieces] ${parts.map(e=>e.name+' '+Number(e.value.toFixed(3))+e.unit).join(' · ')||'Special effect'}${active?' · Active':''}`,active?'tooltip-effect':'muted'));}}for(const e of effects.entries)if(e.value!==0)card.append(el('div',e.name+': '+Number(e.value.toFixed(3))+e.unit,'tooltip-effect'));for(const roll of entry.synthesisRolls||[]){const g=rules.synthesis?.groups[roll.group];if(g){const e=EquipmentEffects.resolve({unit_attribute_id:g.unit_attribute_id,unit_modifier_type_id:g.unit_modifier_type_id,value:roll.value,linear_level_bonus:0},item.level,effectDB);card.append(el('div',e.reason?'Synthesis: '+e.reason:e.name+': '+Number(e.value.toFixed(3))+e.unit,'tooltip-effect'));}}if(entry.temper&&!['Lute','Flute'].includes(item.category))card.append(el('div',`Temper: physical +${entry.temper.physical||0}% · magic +${entry.temper.magic||0}%`));for(const e of entry.synthesis||[])card.append(el('div',CharacterStats.effects[e.key][0]+': '+e.value+(CharacterStats.effects[e.key][1]==='%'?'%':'')));for(const [label,ids]of [['Lunafrost / Lunastone',[entry.enchant||entry.lunasigil].filter(id=>id&&Sockets.enchantCompatible(find('items',id)||{},item,rules))],['Lunagem sockets',entry.gems||[]]])if(ids.length){card.append(el('h4',label));for(const id of ids){const g=find('items',id);if(!g)continue;const row=el('div',undefined,'tooltip-gem');row.append(itemIcon(g,'✧',Math.max(0,g.grade)),el('span',label==='Lunagem sockets'?gemEffectText(g):g.name+' · '+gemEffectText(g)));card.append(row);}}for(const special of effectDB.gem_special_effects?.[item.id]||[])card.append(el('div',special.name+' '+(special.value>0?'+':'')+special.value+special.unit,'tooltip-effect'));if(effects.pending.length)card.append(el('small',effects.pending.length+' unresolved effects; see item details.','muted'));const parent=target.closest('dialog')||document.body;parent.append(card);const rect=target.getBoundingClientRect();card.style.left=Math.max(8,Math.min(rect.right+10,innerWidth-card.offsetWidth-8))+'px';card.style.top=Math.max(8,Math.min(rect.top,innerHeight-card.offsetHeight-8))+'px';}target.addEventListener('mouseenter',show);target.addEventListener('mouseleave',()=>{leaveTimer=setTimeout(()=>{if(!card?.matches(':hover'))hide();},120);});target.addEventListener('focus',show);target.addEventListener('blur',hide);target.addEventListener('click',hide);}

function renderPassives(){const container=$('passiveResults');container.replaceChildren();state.passives??=[];state.conditions??=[];for(const p of Object.values(effectDB.passives||{}).filter(p=>state.classes.includes(P.abilities[p.ability_id-1]))){const buff=find('buffs',p.buff_id);if(!buff)continue;const chosen=state.passives.includes(p.id),card=el('div',undefined,'card'+(chosen?' selected':''));card.append(itemIcon(buff,'✦'),el('strong',buff.name),el('small',names[P.abilities[p.ability_id-1]]+' · '+p.req_points+' prerequisite points'),el('p',clean(p.description),'muted'));const b=el('button',chosen?'✓ Remove passive':'+ Select passive');b.onclick=()=>{state.passives=chosen?state.passives.filter(id=>id!==p.id):[...state.passives,p.id];state.conditions=state.conditions.filter(id=>state.passives.includes(id));if(chosen)state.buffs=state.buffs.filter(id=>!p.children.some(c=>c.buff_id===id)&&!p.related?.includes(id));render();};card.append(b);if(chosen&&p.conditional&&p.buff_id!==831&&(effectDB.buffs[p.buff_id]?.modifiers||[]).length){const label=el('label','Condition active: ','check'),input=el('input');input.type='checkbox';input.checked=state.conditions.includes(p.id);input.onchange=()=>{state.conditions=input.checked?[...state.conditions,p.id]:state.conditions.filter(id=>id!==p.id);if(!input.checked)state.buffs=state.buffs.filter(id=>!p.children.some(c=>c.buff_id===id)&&!p.related?.includes(id));render();};label.append(input);card.append(label);}if(chosen&&(!p.conditional||state.conditions.includes(p.id)||!(effectDB.buffs[p.buff_id]?.modifiers||[]).length))for(const child of [...p.children,...(p.related||[]).filter(id=>!p.children.some(c=>c.buff_id===id)).map(buff_id=>({buff_id,related:true}))]){const c=find('buffs',child.buff_id);if(!c)continue;const label=el('label',c.name+(child.related?' · related timed buff active (verify requirement): ':' · triggered effect active: '),'check'),input=el('input');input.type='checkbox';input.checked=state.buffs.includes(c.id);input.onchange=()=>{state.buffs=input.checked?[...new Set([...state.buffs,c.id])]:state.buffs.filter(id=>id!==c.id);render();};label.append(input);card.append(label);}container.append(card);}renderBuffIcons();}

document.addEventListener('keydown',event=>{if(event.key==='Escape')hoverCard?.remove();});document.addEventListener('scroll',event=>{if(!event.target.closest?.('.item-tooltip'))hoverCard?.remove();},true);

function synthesisEditor(panel,item,rolls,legacy,getGrade){
const section=el('section',undefined,'synthesis-editor'),heading=el('h3','Synthesis effects'),hint=el('p',undefined,'muted'),rows=el('div'),add=el('button','+ Add synthesis effect');section.append(heading,hint,rows,add);panel.append(section);
function draw(){const grade=getGrade(),choices=Synthesis.choices(item,grade,rules,effectDB),capacity=Synthesis.capacity(grade,item,rules);section.hidden=!choices.length&&!rolls.length&&!legacy.length;hint.textContent=`${rolls.length} / ${capacity} effects · ${grades[grade]} · Database ranges for this item. Choose an actual roll; changing grade does not silently reroll effects.`;rows.replaceChildren();if(legacy.length){const old=el('div',undefined,'effect pending'),clear=el('button','Remove legacy synthesis');old.append(el('p','This saved item has legacy manual synthesis values. Remove them and select database rolls below. They remain preserved until removed.'),clear);clear.onclick=()=>{legacy.splice(0);draw();};rows.append(old);}if(!choices.length)rows.append(el('p','No nonzero synthesis rolls in the database for this item and grade.','muted'));
for(const roll of rolls){const row=el('div',undefined,'synthesis-row'),select=el('select'),input=el('input'),remove=el('button','×'),range=el('small',undefined,'muted'),max=el('button','Max');const current=choices.find(g=>g.id===roll.group);for(const g of choices.filter(g=>g.id===roll.group||!rolls.some(r=>rules.synthesis.groups[r.group]?.unit_attribute_id===g.unit_attribute_id))){const o=el('option',g.name+(g.unit==='%'?' (%)':''));o.value=g.id;select.append(o);}if(!current){const o=el('option','Unavailable at this grade / item');o.value=roll.group;select.append(o);row.classList.add('pending');}select.value=roll.group;select.setAttribute('aria-label','Synthesis effect');const scale=current?.scale||1;input.type='number';input.step=scale;input.value=Number((roll.value*scale).toFixed(5));input.setAttribute('aria-label','Synthesis roll value');if(current){input.min=current.min*scale;input.max=current.max*scale;range.textContent=`${Number((current.min*scale).toFixed(4))} to ${Number((current.max*scale).toFixed(4))}${current.unit}`;}else range.textContent='Remove or change this effect before equipping.';input.oninput=()=>{const value=Number(input.value)/scale;roll.value=Math.abs(value-Math.round(value))<1e-6?Math.round(value):value;};select.onchange=()=>{const next=choices.find(g=>g.id===Number(select.value));roll.group=next.id;roll.value=next.grades[grade].max;draw();};remove.setAttribute('aria-label','Remove synthesis effect');remove.onclick=()=>{rolls.splice(rolls.indexOf(roll),1);draw();};max.disabled=!current;max.onclick=()=>{roll.value=current.grades[grade].max;draw();};row.append(select,input,max,remove,range);rows.append(row);}
add.disabled=rolls.length>=capacity||!choices.some(g=>!rolls.some(r=>rules.synthesis.groups[r.group]?.unit_attribute_id===g.unit_attribute_id));add.onclick=()=>{const g=choices.find(g=>!rolls.some(r=>rules.synthesis.groups[r.group]?.unit_attribute_id===g.unit_attribute_id));if(g){rolls.push({group:g.id,value:g.grades[grade].max});draw();}};}
draw();return draw;}

$('toggleProvenance').onclick=()=>{const content=$('provenanceContent'),button=$('toggleProvenance');content.hidden=!content.hidden;button.setAttribute('aria-expanded',String(!content.hidden));button.textContent=(content.hidden?'Show':'Hide')+' data, effects and limitations';};
function attachBuffTooltip(target,buff,audit){let card,timer;function hide(){card?.remove();if(hoverCard===card)hoverCard=null;}function show(){hoverCard?.remove();card=el('aside',undefined,'item-tooltip');hoverCard=card;card.setAttribute('role','tooltip');const header=el('div',undefined,'tooltip-header');header.append(itemIcon(buff,'✦'),el('strong',buff.name));card.append(header);const gradeSet=audit.armorGradeBuffs?.find(x=>x.id===buff.id);if(gradeSet)card.append(el('div',gradeSet.pieces+' eligible '+gradeSet.kind+' pieces · lowest grade '+grades[gradeSet.grade]));const entries=audit.entries.filter(e=>e.buff_id===buff.id);for(const e of entries)card.append(el('div',e.name+': '+(e.value>0?'+':'')+Number(e.value.toFixed(3))+e.unit,'tooltip-effect'));const source='Buff #'+buff.id;for(const e of audit.pending.filter(e=>e.source===source||e.source?.startsWith(source+' · '))){const m=e.raw;if(m?.unit_attribute_id){const metadata=effectDB.attributes[m.unit_attribute_id];card.append(el('div',(metadata?.name||'Attribute #'+m.unit_attribute_id)+': '+(m.unit_modifier_type_id===1?EquipmentEffects.roundEven(m.value+m.linear_level_bonus*(e.level??55)/100)+'% of base · ':'')+(m.unit_modifier_type_id===1&&['str','dex','sta','int','spi','heal_dps','heal_dps_inc','spell_dps','spell_dps_inc','melee_dps_inc','ranged_dps_inc','armor','magic_resist','max_health','max_mana'].includes(metadata?.attribute)?'Applied to build totals':e.reason),'muted'));}else card.append(el('div',e.reason,'muted'));}if(!entries.length)card.append(el('small','No direct verified stat contribution.','muted'));card.append(el('small',clean(buff.description||''),'muted'));card.addEventListener('mouseenter',()=>clearTimeout(timer));card.addEventListener('mouseleave',hide);document.body.append(card);const rect=target.getBoundingClientRect();card.style.left=Math.max(8,Math.min(rect.right+10,innerWidth-card.offsetWidth-8))+'px';card.style.top=Math.max(8,Math.min(rect.top,innerHeight-card.offsetHeight-8))+'px';}target.addEventListener('mouseenter',show);target.addEventListener('mouseleave',()=>{timer=setTimeout(()=>{if(!card?.matches(':hover'))hide();},120);});target.addEventListener('focus',show);target.addEventListener('blur',hide);target.addEventListener('click',show);}

function skillBuffEditor(card,skill){const ranks=rules.skill_buffs[skill.id],active=ranks.find(r=>state.buffs.includes(r.buff_id));let choice=active||ranks.filter(r=>r.start_level<=state.level&&r.end_level>=state.level).at(-1)||ranks[0];const label=el('label','Buff rank'),select=el('select');select.setAttribute('aria-label',skill.name+' buff rank');for(const rank of ranks){const option=el('option','Rank '+rank.rank+' · level '+rank.start_level+'–'+rank.end_level);option.value=rank.buff_id;select.append(option);}select.value=choice.buff_id;select.onchange=()=>{choice=ranks.find(r=>r.buff_id===Number(select.value));if(active){state.buffs=state.buffs.filter(id=>!ranks.some(r=>r.buff_id===id));state.buffs.push(choice.buff_id);render();}};label.append(select);card.append(label);const toggle=el('label','Buff active (verify requirements)','check'),input=el('input');input.type='checkbox';input.checked=!!active;input.setAttribute('aria-label',skill.name+' buff active');input.onchange=()=>{state.buffs=state.buffs.filter(id=>!ranks.some(r=>r.buff_id===id));if(input.checked)state.buffs.push(choice.buff_id);render();};toggle.append(input);card.append(toggle);}

function renderBuffIcons(){const audit=equipmentSummary().effects;$('activeBuffCount').textContent=audit.manualBuffs?.length||0;$('passiveBuffCount').textContent=audit.passiveBuffs?.length||0;$('activeBuffIcons').replaceChildren();for(const button of $('buffDisplayTabs').children)button.classList.toggle('active',button.dataset.buffTab===buffDisplay);for(const id of (buffDisplay==='passive'?audit.passiveBuffs:audit.manualBuffs)||[]){const buff=find('buffs',id);if(!buff)continue;const icon=itemIcon(buff,'✦');icon.tabIndex=0;icon.classList.add('buff-icon');icon.setAttribute('aria-label',buff.name);attachBuffTooltip(icon,buff,audit);if(buffDisplay==='active'){const chip=el('div',undefined,'active-buff-chip'),remove=el('button','×','remove-active-buff');remove.type='button';remove.setAttribute('aria-label','Remove '+buff.name);remove.title='Remove '+buff.name;remove.onclick=e=>{e.stopPropagation();state.buffs=state.buffs.filter(selected=>selected!==id);hoverCard?.remove();render();};chip.append(icon,remove);$('activeBuffIcons').append(chip);}else $('activeBuffIcons').append(icon);}}
$('buffDisplayTabs').onclick=e=>{const button=e.target.closest('button');if(!button?.dataset.buffTab)return;hoverCard?.remove();buffDisplay=button.dataset.buffTab;renderBuffIcons();};

document.addEventListener('click',e=>{if(!e.target.closest('.buff-icon,.item-tooltip'))hoverCard?.remove();});
